UPDATE public.pages SET
  title = CASE slug
    WHEN 'about' THEN 'About Medi Pharma UK'
    WHEN 'contact' THEN 'Contact our care team'
    ELSE title END,
  subtitle = CASE slug
    WHEN 'about' THEN 'A UK supplier of lab-verified, pharmacy-grade medication.'
    WHEN 'contact' THEN 'Seven days a week, from our Manchester support desk.'
    ELSE subtitle END
WHERE slug IN ('about','contact');

ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
