INSERT INTO public.categories (slug, name, description, image_url, sort_order, is_visible) VALUES
('oral-treatments','Oral Treatments','Tablet and capsule formulations, dosed and blister sealed.','https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=900&q=80',1,true),
('injectables','Injectables','Sterile ampoules and multi-dose vials from licensed labs.','https://images.unsplash.com/photo-1587854692152-cbe660dbde88?auto=format&fit=crop&w=900&q=80',2,true),
('post-cycle-support','Post-Cycle Support','Recovery protocols to restore natural balance after a course.','https://images.unsplash.com/photo-1631549916768-4119b2e5f926?auto=format&fit=crop&w=900&q=80',3,true),
('peptides-hgh','Peptides & HGH','Lyophilised peptides and growth hormone, cold-chain shipped.','https://images.unsplash.com/photo-1603398938378-e54eab446dde?auto=format&fit=crop&w=900&q=80',4,true),
('fat-loss','Fat Loss','Thermogenic and metabolic support, clinically dosed.','https://images.unsplash.com/photo-1550572017-edd951b55104?auto=format&fit=crop&w=900&q=80',5,true),
('sexual-health','Sexual Health','Discreet ED and libido treatments in plain packaging.','https://images.unsplash.com/photo-1607619056574-7b8d3ee536b2?auto=format&fit=crop&w=900&q=80',6,true),
